function granularProcess(samples, opts){
  opts = opts || {};
  var grain = Math.max(1, opts.grain != null ? opts.grain : 512);
  var stretch = opts.stretch != null ? opts.stretch : 1.5;   // >1 拉长
  if(stretch <= 0) stretch = 1;
  var overlap = Math.max(1, opts.overlap != null ? opts.overlap : 2);
  var hopIn = grain;
  var hopOut = Math.max(1, Math.round(grain * stretch));
  var n = samples.length;
  var out = new Array(Math.ceil(n*stretch) + grain).fill(0);
  var norm = new Array(out.length).fill(0);
  var pos = 0;
  for(var gi=0; gi<n; gi+=hopIn){
    var start = Math.round(pos);
    for(var k=0; k<grain && gi+k<n; k++){
      var oi = start + k; if(oi >= out.length) break;
      var w = 0.5 - 0.5*Math.cos(2*Math.PI*k/grain);   // 汉宁窗
      out[oi] += samples[gi+k]*w;
      norm[oi] += w;
    }
    pos += hopOut;
  }
  for(var i=0;i<out.length;i++){ if(norm[i] > 0) out[i] /= norm[i]; }
  return out;
}
function granularAnalyze(samples, opts){
  var out = granularProcess(samples, opts);
  var peak=0, sum=0;
  for(var i=0;i<out.length;i++){ var a=Math.abs(out[i]); if(a>peak)peak=a; sum+=out[i]*out[i]; }
  return { inLength: samples.length, outLength: out.length, stretch: opts.stretch != null ? opts.stretch : 1.5, peak: peak, rms: Math.sqrt(sum/out.length) };
}

var EXPORTS={granularAnalyze:granularAnalyze,granularProcess:granularProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GranularForgePure = EXPORTS; }
